const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const toliara = ee.Geometry.Point(43.6666, -23.35); // Toliara, Madagascar

  // Recent Period: September 2021 AND September 2022
  const startRecent1 = '2021-09-01';
  const endRecent1 = '2021-09-30';
  const startRecent2 = '2022-09-01';
  const endRecent2 = '2022-09-30';

  // Historic Period: September 2000-2015 (average for September each year)
  const startHistoricYear = 2000;
  const endHistoricYear = 2015;
  const month = 9; // September

  // 2. Data Acquisition & Preprocessing Helper Function
  const getLandsatCollection = (startDate, endDate, geometry) => {
    // Landsat 8/9 for recent
    let collection = ee.ImageCollection('LANDSAT/LC08/C02/SR')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .map(image => image.addBands(image.normalizedDifference(['B5', 'B4']).rename('NDVI'))) // NIR B5, Red B4
      .map(image => image.updateMask(image.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0))); // Mask clouds (bit 3: cloud)

    // Fallback/Supplement with Landsat 7/5 for historic
    const landsat7 = ee.ImageCollection('LANDSAT/LE07/C02/SR')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .map(image => image.addBands(image.normalizedDifference(['B4', 'B3']).rename('NDVI'))) // NIR B4, Red B3
      .map(image => image.updateMask(image.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0))); // Mask clouds (bit 3: cloud)

    const landsat5 = ee.ImageCollection('LANDSAT/LT05/C02/SR')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .map(image => image.addBands(image.normalizedDifference(['B4', 'B3']).rename('NDVI'))) // NIR B4, Red B3
      .map(image => image.updateMask(image.select('QA_PIXEL').bitwiseAnd(1 << 3).eq(0))); // Mask clouds (bit 3: cloud)

    // Combine collections
    return collection.merge(landsat7).merge(landsat5).select('NDVI');
  };

  // 3. Process Recent Period (September 2021 and September 2022)
  let recentCollection1 = getLandsatCollection(startRecent1, endRecent1, toliara);
  let recentCollection2 = getLandsatCollection(startRecent2, endRecent2, toliara);

  const recentCount1 = recentCollection1.size().getInfo();
  const recentCount2 = recentCollection2.size().getInfo();

  if (recentCount1 === 0 && recentCount2 === 0) {
    console.log("No images found for September 2021 and September 2022.");
    console.log("C1");
    return;
  }

  // Combine and take median for recent period
  const recentCombined = recentCollection1.merge(recentCollection2);
  const recentImagesCount = recentCombined.size().getInfo();

  if (recentImagesCount === 0) {
    console.log("No images found for the recent period (Sept 2021-2022).");
    console.log("C1");
    return;
  }

  const recentNDVI = recentCombined.median();

  const recentPixelCount = await recentNDVI.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: toliara,
    scale: 300, // Landsat resolution
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (recentPixelCount === 0) {
    console.log(`Recent period images: ${recentImagesCount}. No valid pixels after masking.`);
    console.log("C2");
    return;
  }

  const recentNDVIValue = await recentNDVI.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: toliara,
    scale: 300,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 4. Process Historic Period (September 2000-2015 average)
  let historicCollections = ee.ImageCollection([]);
  let totalHistoricImages = 0;
  for (let year = startHistoricYear; year <= endHistoricYear; year++) {
    const startDate = `${year}-${month}-01`;
    const endDate = `${year}-${month}-30`;
    let annualCollection = getLandsatCollection(startDate, endDate, toliara);
    totalHistoricImages += annualCollection.size().getInfo();
    historicCollections = historicCollections.merge(annualCollection);
  }

  if (historicCollections.size().getInfo() === 0) {
    console.log(`Historic period images: ${totalHistoricImages}. No images found for historic period (Sept 2000-2015).`);
    console.log("C1");
    return;
  }

  const historicNDVI = historicCollections.median();

  const historicPixelCount = await historicNDVI.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: toliara,
    scale: 300,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  if (historicPixelCount === 0) {
    console.log(`Historic period images: ${totalHistoricImages}. No valid pixels after masking.`);
    console.log("C2");
    return;
  }

  const historicNDVIValue = await historicNDVI.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: toliara,
    scale: 300,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  // 5. Validation & Final Answer
  if (recentNDVIValue === null || isNaN(recentNDVIValue) ||
      historicNDVIValue === null || isNaN(historicNDVIValue)) {
    console.log("Calculation resulted in None/NaN for one or both periods.");
    console.log("C3");
    return;
  }

  console.log(`Recent NDVI (Sept 2021-2022): ${recentNDVIValue.toFixed(3)} (Images: ${recentImagesCount}, Valid Pixels: ${recentPixelCount})`);
  console.log(`Historic NDVI (Sept 2000-2015 Avg): ${historicNDVIValue.toFixed(3)} (Images: ${totalHistoricImages}, Valid Pixels: ${historicPixelCount})`);

  if (recentNDVIValue < historicNDVIValue) {
    console.log("A"); // Yes, vegetation greenness decreased
  } else {
    console.log("B"); // No, vegetation greenness did not decrease
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
